    def update(self, new_settings, persist=True, validate=False):
        """
        Replaces the current settings with the incoming dict.

        If a setting is missing from `new_settings`:
            * Hidden settings that have a value remain as-is.
            * All other missing settings are set to their default value.

        If `validate` is True, values that are not members of the setting's
        selection_options are skipped (the current value is retained) instead
        of being applied. Used when loading settings from disk (a tampered or
        corrupted settings.json must not be able to inject an invalid value).
        """
        for key, value in new_settings.items():
            self._platform.check(key, value)
        for entry in SettingsDefinition.settings_entries:
            if entry.attr_name not in new_settings:
                if (
                    entry.visibility == SettingsConstants.VISIBILITY__HIDDEN
                    and entry.attr_name in self._data
                ):
                    new_settings[entry.attr_name] = self._data[entry.attr_name]
                else:
                    new_settings[entry.attr_name] = self._default_value(entry.attr_name)
            elif entry.type == SettingsConstants.TYPE__MULTISELECT:
                if type(new_settings[entry.attr_name]) == str:
                    new_settings[entry.attr_name] = [
                        value for value in new_settings[entry.attr_name].split(',') if value.strip()
                    ]
                elif (
                    type(new_settings[entry.attr_name]) == list
                    and len(new_settings[entry.attr_name]) > 0
                    and (type(new_settings[entry.attr_name][0]) in [list, tuple])
                ):
                    new_settings[entry.attr_name] = [v[0] for v in new_settings[entry.attr_name]]
                if not new_settings[entry.attr_name]:
                    new_settings[entry.attr_name] = self._default_value(entry.attr_name)
        for key, value in new_settings.items():
            if validate:
                if key == SettingsConstants.SETTING__PERSISTENT_SETTINGS:
                    entry = None
                else:
                    entry = SettingsDefinition.get_settings_entry(key)
                if entry and entry.selection_options:
                    valid_values = [
                        opt[0] if type(opt) == tuple else opt for opt in entry.selection_options
                    ]
                    incoming = value if isinstance(value, list) else [value]
                    if any((v not in valid_values for v in incoming)):
                        pass
